import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.filter.js";
/*eslint-disable*/
import CreateUnit from "@/components/MaterialManagement/Popups/CreateUnit.vue";
import EditProjectsite from "@/components/MaterialManagement/Popups/EditProjectsite.vue";
import DeleteUnit from "@/components/MaterialManagement/Popups/DeleteUnit.vue";
import { create_list_edit_delete_units } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    SnackBar,
    EditProjectsite,
    DeleteUnit,
    CreateUnit
  },
  data() {
    return {
      unitHeaders: [{
        title: "Unit Name",
        value: "material_unit_name",
        sortable: true,
        align: "start"
      }, {
        title: "Actions",
        value: "actions",
        sortable: false,
        align: "center"
      }],
      fixed: true,
      tableData: [],
      tableLoading: false,
      componentCheck: 0,
      SnackBarComponent: {},
      unitcreation: false,
      rowInfo: {},
      unitdeletion: false,
      search: "",
      currentPage: 1,
      itemsPerPage: 10,
      sortBy: [{
        key: "material_unit_name",
        order: "asc"
      }],
      windowHeight: 0
    };
  },
  created() {
    this.windowHeight = window.innerHeight - 310;
    this.fetch_projectsite(); // Updated to modern structure
  },
  watch: {
    search() {
      this.currentPage = 1;
    },
    currentPage(newVal) {
      // When the page changes, scroll to top of the card container
      this.$nextTick(() => {
        const cardContainer = document.querySelector(".card-container");
        if (cardContainer) {
          cardContainer.scrollIntoView({
            behavior: "smooth",
            block: "start"
          });
        } else {
          // Fallback to scrolling to top of page
          window.scrollTo({
            top: 0,
            behavior: "smooth"
          });
        }
      });
    }
  },
  computed: {
    filteredItems() {
      if (!this.search || this.search.trim() === "") {
        return this.tableData;
      }
      const searchTerm = this.search.toLowerCase().trim();
      return this.tableData.filter(item => item.material_unit_name.toLowerCase().includes(searchTerm));
    },
    sortedAndPaginatedItems() {
      // First sort the filtered items
      const sortedItems = this.filteredItems.slice().sort((a, b) => {
        for (const sort of this.sortBy) {
          const aValue = this.getSortValue(a[sort.key], sort.key);
          const bValue = this.getSortValue(b[sort.key], sort.key);
          if (aValue < bValue) return sort.order === "asc" ? -1 : 1;
          if (aValue > bValue) return sort.order === "asc" ? 1 : -1;
        }
        return 0;
      });

      // Then paginate
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      return sortedItems.slice(start, end);
    },
    totalItems() {
      return this.filteredItems.length;
    },
    pageCount() {
      return Math.ceil(this.totalItems / this.itemsPerPage);
    },
    visiblePages() {
      const pages = [];
      const start = Math.max(1, this.currentPage - 2);
      const end = Math.min(this.pageCount, this.currentPage + 2);
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    }
  },
  methods: {
    getSortValue(value, key) {
      if (!value) return "";
      if (key === "material_unit_name") {
        return value.toLowerCase();
      }
      return value;
    },
    handleSortChange(newSortBy) {
      this.sortBy = newSortBy;
      this.currentPage = 1; // Reset to first page when sorting changes
    },
    open_deletedailog(value) {
      this.rowInfo = value;
      this.componentCheck = 1;
      this.unitdeletion = true;
    },
    create_unit() {
      this.componentCheck = 2;
      this.unitcreation = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.tableData = [];
      this.unitdeletion = false;
      this.unitcreation = false;
      this.fetch_projectsite();
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    },
    async fetch_projectsite() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_units, {
          input: {
            action_type: "LIST_UNIT",
            organization_id: data.organization.organization_id
          }
        }));
        this.tableLoading = false;
        var response = JSON.parse(result.data.create_list_edit_delete_units);
        this.tableLoading = false;
        this.tableData = response.data || [];
      } catch (error) {
        this.tableLoading = false;
        this.tableData = [];
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    goBack() {
      this.$emit('backAction');
    }
  }
};
